"""Ordered-moment Add/LayerNorm candidate generated by Inductor.

An opt-in numerical algorithm, admitted only by complete-output validation.
The source specifies its accumulation and contraction boundaries explicitly;
backend buffering is not permitted to reassociate them.
"""
import hashlib
import math
import operator
from pathlib import Path

import torch
from torch._inductor import ir
from torch._inductor.lowering import register_lowering
from torch._inductor.select_algorithm import TritonTemplate, TritonTemplateKernel
from torch._inductor.virtualized import V


@torch.library.custom_op('flagtree_p800::ordered_add_layernorm', mutates_args=())
def _op(a: torch.Tensor, b: torch.Tensor, w: torch.Tensor, shift: torch.Tensor,
        eps: float, dual: bool, revision: str) -> torch.Tensor:
    z = a + b
    y = torch.nn.functional.layer_norm(z, (z.shape[-1],), w, shift, eps)
    return torch.stack((z, y) if dual else (y,))


@_op.register_fake
def _fake(a, b, w, shift, eps, dual, revision):
    return a.new_empty((2 if dual else 1, *a.shape))


def p800_ordered_config(*args, **kwargs):
    from torch._inductor.runtime.triton_heuristics import template
    from ._p800_model_schedule import _compile_buffer_option, _validate_buffer_option
    decorate = template(*args, **kwargs)
    width = kwargs.get('inductor_meta', {}).get('config_args', {}).get('N', 0)
    resident = type(width) is int and 128 <= width <= 1024 and width % 64 == 0
    def apply(fn):
        tuner = decorate(fn)
        original = tuner._precompile_config
        def compile_config(*a, **kw):
            with _compile_buffer_option(fn, 2048, reduction_tree=True, fp_fusion=False,
                                        unroll_control=False, row_shared=True,
                                        ordered_row_reuse=resident,
                                        # Correct prefetching is available in mode 2,
                                        # but does not yet show a stable E2E gain
                                        # for this ordered multi-output candidate.
                                        dma_pipeline=1 if resident else None) as forwarded:
                result = original(*a, **kw)
            binary = getattr(result, 'kernel', result)
            tuner.p800_buffer_choice = _validate_buffer_option(binary, 2048, forwarded)
            if (binary.metadata.enable_fp_fusion or not binary.metadata.xpu_reduction_tree
                    or not binary.metadata.isCloseUnrollControl or not binary.metadata.xpu_row_shared):
                raise RuntimeError('Ordered LayerNorm arithmetic options were dropped')
            if resident and (not binary.metadata.xpu_ordered_row_reuse or
                             binary.metadata.xpu_dma_pipeline != 1 or
                             not binary.metadata.dma_pipeline.get('ordered_row_requested')):
                raise RuntimeError('Ordered LayerNorm row residency was dropped')
            return result
        tuner._precompile_config = compile_config
        return tuner
    return apply


class _Kernel(TritonTemplateKernel):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._register_extra_template_env_fns(self.output_pointer)

    def output_pointer(self):
        with self.create_subgraph_body('<STORE_OUTPUT>'):
            output = self.args.output(self.output_node.get_name())
        return self._register_hook('<STORE_OUTPUT>', lambda: output)

    def jit_lines(self):
        return super().jit_lines().replace('@triton_heuristics.template(', '@p800_ordered_config(')


class _Template(TritonTemplate):
    kernel_type = _Kernel


def _grid(outputs, m, n, meta):
    return ((m + meta['ROWS'] - 1) // meta['ROWS'], 1, 1)


# Pack both independent 16-lane accumulators into a 32-element tensor. Each
# narrow input then occupies a full FP16 vector; widening retains two FP32
# vectors. Their addition precedes the same 8/4/2/1 within-vector reduction.
_SOURCE = '''
from triton.experimental.graph_fusion._p800_ordered_layernorm import p800_ordered_config
{{def_kernel("A", "B", "W", "SHIFT")}}
    Out = {{output_pointer()}}
    row = tl.program_id(0) * ROWS + tl.arange(0, ROWS)[:, None]
    lane = tl.arange(0, 32)[None, :]
    offset = (lane // 16) * 32 + lane % 16
    total = tl.full((ROWS, 32), 0.0, tl.float32)
    squares = tl.full((ROWS, 32), 0.0, tl.float32)
    for block in range(N // 64):
'''
for j in range(2):
    _SOURCE += f'''        c{j} = block * 64 + {j*16} + offset
        a{j} = tl.load(A + row * N + c{j}, row < M, other=0).to(tl.float32)
        b{j} = tl.load(B + (row % BROWS) * N + c{j}, row < M, other=0).to(tl.float32)
        z{j} = (a{j} + b{j}).to(tl.float16).to(tl.float32)
'''
_SOURCE += '''        total = (total + z0) + z1
        squares = tl.fma(z1, z1, tl.fma(z0, z0, squares))
    mean = tl.div_rn(tl.sum(total, 1), N)[:, None]
    square_mean = tl.div_rn(tl.sum(squares, 1), N)[:, None]
    variance = square_mean - mean * mean
    inv = tl.rsqrt(variance + EPS)
    for block in range(N // 64):
'''
# Affine output has no accumulator grouping constraint. Write consecutive
# 32-element FP16 packets so each DMA covers a full 64-byte cache line.
for j in range(2):
    _SOURCE += f'''        c{j} = block * 64 + {j*32} + lane
        a{j} = tl.load(A + row * N + c{j}, row < M, other=0).to(tl.float32)
        b{j} = tl.load(B + (row % BROWS) * N + c{j}, row < M, other=0).to(tl.float32)
        z{j} = (a{j} + b{j}).to(tl.float16).to(tl.float32)
        w{j} = tl.load(W + c{j}).to(tl.float32)
        t{j} = tl.load(SHIFT + c{j}).to(tl.float32)
        v{j} = (z{j} - mean) * inv
'''
    _SOURCE += (f'        y{j} = tl.fma(v{j}, w{j}, t{j})\n' if j == 0 else
                f'        y{j} = (v{j} * w{j}) + t{j}\n')
    _SOURCE += f'''        if DUAL:
            tl.store(Out + row * N + c{j}, z{j}.to(tl.float16), row < M)
        tl.store(Out + (M * N if DUAL else 0) + row * N + c{j}, y{j}.to(tl.float16), row < M)
'''
_template = _Template('flagtree_ordered_add_layernorm', _grid, _SOURCE)
_revision = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()


@register_lowering(torch.ops.flagtree_p800.ordered_add_layernorm.default, type_promotion_kind=None)
def _lower(a, b, w, shift, eps, dual, revision):
    shape = list(map(int, a.get_size()))
    n = shape[-1]; m = math.prod(shape[:-1]); brows = math.prod(b.get_size()) // n
    aa = ir.ExternKernel.require_contiguous(a)
    bb = ir.ExternKernel.require_contiguous(b)
    ww = ir.ExternKernel.require_contiguous(w)
    tt = ir.ExternKernel.require_contiguous(shift)
    layout = ir.FixedLayout(a.get_device(), a.get_dtype(), [2 if dual else 1, m, n], [m*n, n, 1])
    choice = _template.generate([aa, bb, ww, tt], layout, num_stages=1, num_warps=8,
                               M=m, N=n, BROWS=brows, EPS=eps, DUAL=dual, ROWS=64)
    output = choice.output_node()
    V.graph.no_fuse_buffer_names.add(output.get_name())
    return ir.TensorBox(ir.View.create(output.data, [2 if dual else 1, *shape]))


def rewrite(gm, inputs):
    """Rewrite a pure matched region; preserve every live output and its order."""
    from ._patterns import _add_layernorm
    values = dict(zip((n for n in gm.graph.nodes if n.op == 'placeholder'), inputs))
    candidates = [(n, _add_layernorm(n)) for n in gm.graph.nodes]
    for norm, match in candidates:
        if match is None or match.kind != 'add_layernorm_affine':
            continue
        if any(n not in values for n in match.inputs):
            continue
        a,b,w,t = match.inputs
        av,bv,wv,tv = [values[n] for n in (a,b,w,t)]
        if not all(isinstance(x,torch.Tensor) and x.dtype == torch.float16 and x.is_contiguous()
                   and x.layout == torch.strided and x.device == av.device
                   and all(type(d) is int for d in x.shape) for x in (av,bv,wv,tv)):
            continue
        if av.ndim < 2 or av.numel() == 0 or av.shape[-1] % 64 or not 64 <= av.shape[-1] <= 2048:
            continue
        n = av.shape[-1]
        if wv.shape != (n,) or tv.shape != (n,):
            continue
        # Only dense residuals or a repeated trailing row; no guessed strides.
        suffix = tuple(bv.shape)
        while len(suffix) > 1 and suffix[0] == 1:
            suffix = suffix[1:]
        if len(suffix) > av.ndim or tuple(av.shape[-len(suffix):]) != suffix:
            continue
        options = dict(match.options)
        if options['normalized_shape'] != (n,) or options['eps'] <= 0:
            continue
        add = match.nodes[0]
        if any(u is not norm and u.op != 'output' for u in add.users):
            continue
        dual = len(add.users) > 1
        with gm.graph.inserting_before(norm):
            packed = gm.graph.call_function(_op._opoverload, (a,b,w,t,options['eps'],dual,_revision))
            y = gm.graph.call_function(operator.getitem,(packed,1 if dual else 0))
            if dual: residual = gm.graph.call_function(operator.getitem,(packed,0))
        norm.replace_all_uses_with(y);gm.graph.erase_node(norm)
        if dual:add.replace_all_uses_with(residual)
        gm.graph.erase_node(add)
        gm.graph.lint();gm.recompile()
        return dict(algorithm='ordered_moments', width=n, dual_output=dual,
                    contract='two ordered sum/square accumulators; tree16; div_rn; explicit affine contraction')
    return None
